    endfunction
    virtual function void build();
      MINOR = uvm_reg_field::type_id::create("MINOR");
      MINOR.configure(this, 8, 0, "RO", 0, 8'h0, 1, 0, 0);
      MAJOR = uvm_reg_field::type_id::create("MAJOR");
      MAJOR.configure(this, 8, 8, "RO", 0, 8'h2, 1, 0, 0);
      CODE = uvm_reg_field::type_id::create("CODE");
      CODE.configure(this, 16, 16, "RO", 0, 16'h4750, 1, 0, 0);
    endfunction
  endclass

