  // ======================= top block =======================
  class mini_soc_reg_block extends uvm_reg_block;
    `uvm_object_utils(mini_soc_reg_block)
    rand mini_soc_gpio_blk gpio;
    rand mini_soc_uart_blk uart;
    rand mini_soc_iommu_blk iommu0_regs;
    uvm_reg_map map;
    function new(string name = "mini_soc_reg_block");
      super.new(name, UVM_NO_COVERAGE);
    endfunction
    virtual function void build();
      map = create_map("map", 0, 4, UVM_LITTLE_ENDIAN, 1);
      default_map = map;
      gpio = mini_soc_gpio_blk::type_id::create("gpio");
      gpio.configure(this);
      gpio.build();
      map.add_submap(gpio.default_map, 'h10000000);
      uart = mini_soc_uart_blk::type_id::create("uart");
      uart.configure(this);
      uart.build();
      map.add_submap(uart.default_map, 'h10001000);
      iommu0_regs = mini_soc_iommu_blk::type_id::create("iommu0_regs");
      iommu0_regs.configure(this);
      iommu0_regs.build();
      map.add_submap(iommu0_regs.default_map, 'h10003000);
      lock_model();
    endfunction
  endclass

  // RAL <-> AXI4: each register access is one INCR burst of one 32-bit beat
  class mini_soc_axi_reg_adapter extends uvm_reg_adapter;
    `uvm_object_utils(mini_soc_axi_reg_adapter)
    function new(string name = "mini_soc_axi_reg_adapter");
      super.new(name);
      supports_byte_enable = 1;
      provides_responses   = 0;      // the AXI driver writes the response into the request
    endfunction
    virtual function uvm_sequence_item reg2bus(const ref uvm_reg_bus_op rw);
      axi4_item t = axi4_item::type_id::create("ral_axi");
      t.write = (rw.kind == UVM_WRITE);
      t.id = 0; t.addr = 32'(rw.addr); t.len = 0; t.size = 3'd2; t.burst = AXI4_INCR;
      t.alloc();
      t.data[0] = 32'(rw.data);
      t.strb[0] = t.write ? 4'(rw.byte_en) : 4'hF;
      if (t.write && t.strb[0] == 4'h0) t.strb[0] = 4'hF;
      return t;
    endfunction
    virtual function void bus2reg(uvm_sequence_item bus_item, ref uvm_reg_bus_op rw);
      axi4_item t;
      if (!$cast(t, bus_item)) `uvm_fatal("RAL_ADAPT", "not an axi4_item")
      rw.kind   = t.write ? UVM_WRITE : UVM_READ;
      rw.addr   = t.addr;
      rw.data   = t.data.size() ? t.data[0] : 0;
      rw.status = (t.resp.size() && t.resp[0] == AXI4_OKAY) ? UVM_IS_OK : UVM_NOT_OK;
    endfunction
  endclass
endpackage
